using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evaluation;

public class EvaluationTests : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder _builder = null!;
    private DistributedApplication _app = null!;

    public async Task InitializeAsync()
    {
        _builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _builder.BuildAsync();
        await _app.StartAsync();
    }

    public async Task DisposeAsync()
    {
        await _app.DisposeAsync();
    }

    [Fact]
    public async Task ChatResponse_IsRelevant()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.NotEmpty(responseText);
        Assert.Contains("Paris", responseText, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task ChatResponse_Evaluation_Coherence()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in two sentences.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.NotEmpty(responseText);

        // Use the evaluator chat client to score the response
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator()
        };

        var chatConfiguration = new ChatConfiguration(chatClient);
        var turnContext = new TurnContext();
        turnContext.AddTurn(messages, response.Messages);

        foreach (var evaluator in evaluators)
        {
            await evaluator.InitializeAsync(chatConfiguration);
        }

        var results = new Dictionary<string, EvaluationResult>();
        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(turnContext, chatConfiguration);
            results[evaluator.GetType().Name] = result;
        }

        // Assert minimum quality thresholds
        foreach (var (name, result) in results)
        {
            foreach (var metric in result.Metrics)
            {
                if (metric.Value is NumericMetricValue numericValue)
                {
                    Assert.True(numericValue.Value >= 3,
                        $"Evaluator {name} metric {metric.Key} scored {numericValue.Value}, expected >= 3");
                }
            }
        }
    }
}

