 using Microsoft.Extensions.AI;
 using Microsoft.Extensions.AI.Evaluation;
 using Microsoft.Extensions.AI.Evaluation.Quality;
 using Microsoft.Extensions.AI.Evaluation.Reporting;
 using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
 using Xunit;

 namespace MyApp.Evaluation;

 public class ChatEvaluationTests
 {
     private static IChatClient CreateChatClient()
     {
         // Configure the chat client using environment variables.
         // Set AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_DEPLOYMENT (defaults to "chat").
         var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
             ?? throw new InvalidOperationException(
                 "Set the AZURE_OPENAI_ENDPOINT environment variable.");

         var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "chat";

         var client = new Azure.AI.OpenAI.AzureOpenAIClient(
             new Uri(endpoint),
             new Azure.Identity.DefaultAzureCredential());

         return client.GetChatClient(deployment).AsIChatClient();
     }

     private static ChatConfiguration CreateChatConfiguration()
     {
         return new ChatConfiguration(CreateChatClient());
     }

     [Fact]
     public async Task ChatResponse_IsRelevant()
     {
         var chatClient = CreateChatClient();

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "What is the capital of France?")
         };

         var response = await chatClient.GetResponseAsync(messages);
         var responseText = response.Text ?? string.Empty;

         Assert.NotEmpty(responseText);
         Assert.Contains("Paris", responseText, StringComparison.OrdinalIgnoreCase);
     }

     [Fact]
     public async Task ChatResponse_Coherence()
     {
         var chatClient = CreateChatClient();
         var chatConfiguration = CreateChatConfiguration();

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "Explain how photosynthesis works in two sentences.")
         };

         var response = await chatClient.GetResponseAsync(messages);

         var evaluator = new CoherenceEvaluator();
         var result = await evaluator.EvaluateAsync(messages, response, chatConfiguration);

         AssertMetricsAboveThreshold(result, threshold: 3);
     }

     [Fact]
     public async Task ChatResponse_Relevance()
     {
         var chatClient = CreateChatClient();
         var chatConfiguration = CreateChatConfiguration();

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "What are the benefits of exercise?")
         };

         var response = await chatClient.GetResponseAsync(messages);

         var evaluator = new RelevanceEvaluator();
         var result = await evaluator.EvaluateAsync(messages, response, chatConfiguration);

         AssertMetricsAboveThreshold(result, threshold: 3);
     }

     [Fact]
     public async Task ChatResponse_CompositeEvaluation()
     {
         var chatClient = CreateChatClient();
         var chatConfiguration = CreateChatConfiguration();

         var messages = new List<ChatMessage>
         {
             new(ChatRole.User, "Summarize the water cycle in three steps.")
         };

         var response = await chatClient.GetResponseAsync(messages);

         var evaluator = new CompositeEvaluator(
             new CoherenceEvaluator(),
             new RelevanceEvaluator());

         var result = await evaluator.EvaluateAsync(messages, response, chatConfiguration);

         AssertMetricsAboveThreshold(result, threshold: 3);
     }

     private static void AssertMetricsAboveThreshold(EvaluationResult result, double threshold)
     {
         foreach (var metric in result.Metrics)
         {
             if (metric.Value is NumericMetric numericMetric && numericMetric.Value.HasValue)
             {
                 Assert.True(numericMetric.Value.Value >= threshold,
                     $"Metric '{metric.Key}' scored {numericMetric.Value.Value}, expected >= {threshold}");
             }
         }
     }
 }

